def sim5(cups_cols, bars, plat, beam=(40,43)):
    occ={}
    for s in cups_cols:
        for rr in range(4,8):
            for cc in range(s,s+12): occ[(rr,cc)]=('cup',s)
        for rr in range(8,12):
            for cc in list(range(s,s+4))+list(range(s+8,s+12)): occ[(rr,cc)]=('cup',s)
    for (r0,r1,c0,c1,tag) in bars:
        for rr in range(r0,r1+1):
            for cc in range(c0,c1+1): occ[(rr,cc)]=tag
    pr0,pr1,pc0,pc1=plat
    for rr in range(pr0,pr1+1):
        for cc in range(pc0,pc1+1): occ[(rr,cc)]=('plat',0)
    hits=set(); seen=set(); rays=[(beam[0],beam[1],63)]; guard=0
    while rays:
        a,b,fromr=rays.pop(); guard+=1
        if guard>300: break
        rr=None
        for r in range(fromr,-1,-1):
            hit=[(r,cc) for cc in range(a,b+1) if (r,cc) in occ]
            if hit: rr=r; break
        if rr is None or rr==0: continue
        tag=occ[hit[0]]
        if tag[0]=='cup' and rr<=7: hits.add(cups_cols.index(tag[1]))
        c0=min(h[1] for h in hit); c1=max(h[1] for h in hit)
        while c0-1>=0 and occ.get((rr,c0-1))==tag: c0-=1
        while c1+1<64 and occ.get((rr,c1+1))==tag: c1+=1
        key=(tag,rr,c0,c1)
        if key in seen: continue
        seen.add(key)
        br=rr+1
        if br+3>63: continue
        lo=max(0,c0-4); hi=min(63,c1+4)
        free=set(cc for cc in range(lo,hi+1) if all((rb,cc) not in occ for rb in range(br,br+4)))
        if not any(c0<=cc<=c1 for cc in free): continue
        segs=set()
        for cc in range(c0,c1+1):
            if cc in free:
                L=cc
                while L-1 in free: L-=1
                R=cc
                while R+1 in free: R+=1
                segs.add((L,R))
        for (L,R) in segs:
            if R-L>=3:
                rays.append((L,L+3,br-1)); rays.append((R-3,R,br-1))
            else:
                rays.append((L,R,br-1))
    return hits
